const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Wilmington, North Carolina geometry
  const wilmingtonCoords = [-77.95, 34.22];
  const point = ee.Geometry.Point(wilmingtonCoords);
  const buffer = point.buffer(50000); // 50 km buffer for robustness

  // 2. Define time period: 2018
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // 3. Load CHIRPS daily rainfall data
  let collection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(buffer);

  // Check if collection is empty
  const collectionSize = collection.size().getInfo();
  console.log(`CHIRPS Images Available: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No CHIRPS data found for 2018 in Wilmington area.');
    console.log('C1');
    return;
  }

  // 4. Sum all daily precipitation for the year (convert mm to inches)
  const totalPrecip = collection
    .reduce(ee.Reducer.sum())
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: buffer,
      scale: 5000,
      maxPixels: 1e9
    })
    .get('precipitation')
    .getInfo();

  // Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = totalPrecip / 25.4;

  // 5. Validate result
  console.log(`Total 2018 Precipitation: ${totalPrecip?.toFixed(2) || 'None'} mm`);
  console.log(`Total 2018 Precipitation: ${precipInches?.toFixed(2) || 'None'} inches`);

  // Check for null or invalid values
  if (totalPrecip === null || totalPrecip === undefined || isNaN(precipInches)) {
    console.log('Calculation failed - invalid data.');
    console.log('C3');
    return;
  }

  // 6. Determine answer: >= 90 inches?
  const threshold = 90;
  console.log(`Threshold: ${threshold} inches`);

  if (precipInches >= threshold) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
